def separate_paren_groups(paren_string: str) -> List[str]:
    """Separate balanced top-level parenthesis groups, ignoring spaces.

    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    groups = []
    current = []
    depth = 0

    for char in paren_string:
        if char.isspace():
            continue

        if char == '(':
            depth += 1
            current.append(char)
        elif char == ')':
            depth -= 1
            current.append(char)

            if depth == 0:
                groups.append(''.join(current))
                current = []
        else:
            raise ValueError(f"Invalid character: {char!r}")

    if depth != 0:
        raise ValueError("Unbalanced parentheses")

    return groups

