def parse_music(music_string: str) -> List[int]:
    """Parse a string of ASCII music notes into a list of beat counts.

    The notes are expected to be separated by whitespace. Supported tokens are:

    * ``o``   – whole note, 4 beats
    * ``o|``  – half note, 2 beats
    * ``.|``  – quarter note, 1 beat

    Any token that is not one of the above will raise a ``ValueError``.
    """
    # Mapping from token to beat count
    NOTE_VALUES = {"o": 4, "o|": 2, ".|": 1}

    if not music_string:
        return []

    beats: List[int] = []
    for token in music_string.split():
        try:
            beats.append(NOTE_VALUES[token])
        except KeyError:
            raise ValueError(f"Unsupported note token: {token!r}")

    return beats

